      "Comment ça marche ?": "How does it work?",
      "Qui sommes-nous ?": "Who are we?",
      "Une histoire de passion et de lien.": "A story of passion and connection.",
      "Chez Zoove, nous croyons que les animaux créent du lien et rendent nos vies plus belles. Ils nous accompagnent, nous rapprochent et contribuent à notre bien-être.": "At Zoove, we believe that animals bring us together and make our lives better. They stand by our side, bring us closer and contribute to our well-being.",
      "Zoove est née d’une conviction : la technologie peut faciliter le quotidien des propriétaires d’animaux et des professionnels, tout en renforçant leur lien.": "Zoove was born from a belief: technology can make everyday life easier for pet owners and professionals while strengthening the bond between them.",
      "Zoove existe pour les aider à nous aider.": "Zoove exists to help them help us.",
      "Notre mission": "Our mission",
      "Améliorer le quotidien des animaux et de ceux qui les aiment.": "To improve everyday life for animals and those who love them.",
      "Nos valeurs": "Our values",
      "Confiance, bienveillance, proximité et innovation.": "Trust, kindness, closeness and innovation.",
      "Notre vision": "Our vision",
      "Un écosystème complet et accessible pour tous les amoureux des animaux.": "A complete and accessible ecosystem for all animal lovers.",
      "Notre engagement": "Our commitment",
      "Soutenir les professionnels et promouvoir le bien-être animal.": "To support professionals and promote animal welfare.",
      "Notre histoire": "Our story",
      "Zoove est né d'une conviction : ": "Zoove was born from a belief: ",
      "les animaux contribuent à notre bonheur, à notre bien-être et aux liens qui nous unissent.": "animals contribute to our happiness, our well-being and the bonds that bring us together.",
      "Fondé par ": "Founded by ",
      "Eddy Nemer, passionné d'animaux et titulaire d'un Master en informatique": "Eddy Nemer, an animal lover with a Master's degree in Computer Science",
      ", Zoove associe technologie et passion du monde animal pour faciliter le quotidien des propriétaires et des professionnels.": ", Zoove combines technology and a passion for animals to make everyday life easier for pet owners and professionals.",
      "Notre ambition : ": "Our ambition: ",
      "développer un écosystème numérique accessible qui simplifie les services animaliers et renforce les liens.": "to develop an accessible digital ecosystem that simplifies pet services and strengthens connections.",
      "En 2026, Zoove a été ": "In 2026, Zoove was named ",
      "lauréat régional du prix Création Talents des Cités en Provence-Alpes-Côte d'Azur": "the regional winner of the Création Talents des Cités award in Provence-Alpes-Côte d'Azur",
      ", une reconnaissance de son potentiel et de son ambition.": ", recognizing its potential and ambition.",
