      "Comment ça marche ?": "¿Cómo funciona?",
      "Qui sommes-nous ?": "¿Quiénes somos?",
      "Une histoire de passion et de lien.": "Una historia de pasión y conexión.",
      "Chez Zoove, nous croyons que les animaux créent du lien et rendent nos vies plus belles. Ils nous accompagnent, nous rapprochent et contribuent à notre bien-être.": "En Zoove, creemos que los animales crean vínculos y hacen que nuestras vidas sean más bonitas. Nos acompañan, nos acercan y contribuyen a nuestro bienestar.",
      "Zoove est née d’une conviction : la technologie peut faciliter le quotidien des propriétaires d’animaux et des professionnels, tout en renforçant leur lien.": "Zoove nació de una convicción: la tecnología puede facilitar el día a día de los dueños de mascotas y de los profesionales, al tiempo que fortalece su vínculo.",
      "Zoove existe pour les aider à nous aider.": "Zoove existe para ayudarles a ayudarnos.",
      "Notre mission": "Nuestra misión",
      "Améliorer le quotidien des animaux et de ceux qui les aiment.": "Mejorar el día a día de los animales y de quienes los quieren.",
