      "Notre histoire": "Nuestra historia",
      "Zoove est né d'une conviction : ": "Zoove nació de una convicción: ",
      "les animaux contribuent à notre bonheur, à notre bien-être et aux liens qui nous unissent.": "los animales contribuyen a nuestra felicidad, a nuestro bienestar y a los vínculos que nos unen.",
      "Fondé par ": "Fundado por ",
      "Eddy Nemer, passionné d'animaux et titulaire d'un Master en informatique": "Eddy Nemer, apasionado por los animales y con un máster en Informática",
      ", Zoove associe technologie et passion du monde animal pour faciliter le quotidien des propriétaires et des professionnels.": ", Zoove combina tecnología y pasión por el mundo animal para facilitar el día a día de los dueños de mascotas y de los profesionales.",
      "Notre ambition : ": "Nuestra ambición: ",
      "développer un écosystème numérique accessible qui simplifie les services animaliers et renforce les liens.": "desarrollar un ecosistema digital accesible que simplifique los servicios para mascotas y fortalezca los vínculos.",
