      "Une histoire de passion et de lien.": "Una storia di passione e legami.",
      "Chez Zoove, nous croyons que les animaux créent du lien et rendent nos vies plus belles. Ils nous accompagnent, nous rapprochent et contribuent à notre bien-être.": "In Zoove crediamo che gli animali creino legami e rendano le nostre vite più belle. Ci accompagnano, ci avvicinano e contribuiscono al nostro benessere.",
      "Zoove est née d’une conviction : la technologie peut faciliter le quotidien des propriétaires d’animaux et des professionnels, tout en renforçant leur lien.": "Zoove nasce da una convinzione: la tecnologia può semplificare la vita quotidiana dei proprietari di animali e dei professionisti, rafforzando al tempo stesso il loro legame.",
      "Zoove existe pour les aider à nous aider.": "Zoove esiste per aiutarli ad aiutarci.",
      "Notre mission": "La nostra missione",
      "Améliorer le quotidien des animaux et de ceux qui les aiment.": "Migliorare la vita quotidiana degli animali e di chi li ama.",
