      "Notre histoire": "La nostra storia",
      "Zoove est né d'une conviction : ": "Zoove nasce da una convinzione: ",
      "les animaux contribuent à notre bonheur, à notre bien-être et aux liens qui nous unissent.": "gli animali contribuiscono alla nostra felicità, al nostro benessere e ai legami che ci uniscono.",
      "Fondé par ": "Fondato da ",
      "Eddy Nemer, passionné d'animaux et titulaire d'un Master en informatique": "Eddy Nemer, appassionato di animali e laureato magistrale in Informatica",
      ", Zoove associe technologie et passion du monde animal pour faciliter le quotidien des propriétaires et des professionnels.": ", Zoove unisce tecnologia e passione per il mondo animale per semplificare la vita quotidiana dei proprietari di animali e dei professionisti.",
      "Notre ambition : ": "La nostra ambizione: ",
      "développer un écosystème numérique accessible qui simplifie les services animaliers et renforce les liens.": "sviluppare un ecosistema digitale accessibile che semplifichi i servizi per gli animali e rafforzi i legami.",
      "En 2026, Zoove a été ": "Nel 2026, Zoove è stato ",
