      "Une histoire de passion et de lien.": "Uma história de paixão e ligação.",
      "Chez Zoove, nous croyons que les animaux créent du lien et rendent nos vies plus belles. Ils nous accompagnent, nous rapprochent et contribuent à notre bien-être.": "Na Zoove, acreditamos que os animais criam laços e tornam as nossas vidas mais bonitas. Acompanham-nos, aproximam-nos e contribuem para o nosso bem-estar.",
      "Zoove est née d’une conviction : la technologie peut faciliter le quotidien des propriétaires d’animaux et des professionnels, tout en renforçant leur lien.": "A Zoove nasceu de uma convicção: a tecnologia pode facilitar o dia a dia dos donos de animais e dos profissionais, reforçando ao mesmo tempo a ligação entre eles.",
