      "Votre expertise peut faire évoluer": "A sua experiência pode ajudar a melhorar",
      "Vous prenez soin des animaux au quotidien. Et nous sommes convaincus que les meilleurs outils se construisent avec ceux qui connaissent réellement leur métier.": "Cuida dos animais todos os dias. E acreditamos que as melhores ferramentas são desenvolvidas com quem conhece verdadeiramente a sua profissão.",
      "C'est pourquoi nous recherchons des toiletteurs, pet sitters, vétérinaires et autres professionnels du monde animal pour découvrir Zoove Pro, tester ses fonctionnalités et partager leurs retours.": "Por isso, procuramos profissionais de tosquia e estética animal, pet sitters, veterinários e outros profissionais do setor animal para descobrir o Zoove Pro, testar as suas funcionalidades e partilhar as suas opiniões.",
