      "Informations relatives à l'éditeur, à l'hébergement et à l'utilisation du site Zoove.": "Informações relativas ao responsável pelo site, ao alojamento e à utilização do site Zoove.",
      "1. Éditeur du site": "1. Responsável pelo site",
