      "Comment ça marche ?": "Wie funktioniert es?",
      "Qui sommes-nous ?": "Wer sind wir?",
      "Une histoire de passion et de lien.": "Eine Geschichte von Leidenschaft und Verbundenheit.",
      "Chez Zoove, nous croyons que les animaux créent du lien et rendent nos vies plus belles. Ils nous accompagnent, nous rapprochent et contribuent à notre bien-être.": "Bei Zoove glauben wir, dass Tiere Verbindungen schaffen und unser Leben bereichern. Sie begleiten uns, bringen uns einander näher und tragen zu unserem Wohlbefinden bei.",
      "Zoove est née d’une conviction : la technologie peut faciliter le quotidien des propriétaires d’animaux et des professionnels, tout en renforçant leur lien.": "Zoove entstand aus der Überzeugung, dass Technologie den Alltag von Tierhaltern und Fachleuten erleichtern und gleichzeitig ihre Verbindung stärken kann.",
      "Zoove existe pour les aider à nous aider.": "Zoove ist da, um ihnen zu helfen, uns zu helfen.",
      "Notre mission": "Unsere Mission",
      "Améliorer le quotidien des animaux et de ceux qui les aiment.": "Den Alltag von Tieren und den Menschen, die sie lieben, verbessern.",
      "Nos valeurs": "Unsere Werte",
      "Confiance, bienveillance, proximité et innovation.": "Vertrauen, Fürsorge, Nähe und Innovation.",
      "Notre vision": "Unsere Vision",
      "Un écosystème complet et accessible pour tous les amoureux des animaux.": "Ein umfassendes und zugängliches Ökosystem für alle Tierliebhaber.",
      "Notre engagement": "Unser Engagement",
      "Soutenir les professionnels et promouvoir le bien-être animal.": "Fachleute unterstützen und das Tierwohl fördern.",
      "Notre histoire": "Unsere Geschichte",
      "Zoove est né d'une conviction : ": "Zoove entstand aus einer Überzeugung: ",
      "les animaux contribuent à notre bonheur, à notre bien-être et aux liens qui nous unissent.": "Tiere tragen zu unserem Glück, unserem Wohlbefinden und den Verbindungen bei, die uns zusammenhalten.",
      "Fondé par ": "Gegründet von ",
      "Eddy Nemer, passionné d'animaux et titulaire d'un Master en informatique": "Eddy Nemer, einem Tierliebhaber mit einem Masterabschluss in Informatik",
      ", Zoove associe technologie et passion du monde animal pour faciliter le quotidien des propriétaires et des professionnels.": ", verbindet Zoove Technologie und Leidenschaft für Tiere, um den Alltag von Tierhaltern und Fachleuten zu erleichtern.",
      "Notre ambition : ": "Unser Ziel: ",
      "développer un écosystème numérique accessible qui simplifie les services animaliers et renforce les liens.": "ein zugängliches digitales Ökosystem zu entwickeln, das Dienstleistungen rund um Tiere vereinfacht und Verbindungen stärkt.",
      "En 2026, Zoove a été ": "Im Jahr 2026 wurde Zoove ",
      "lauréat régional du prix Création Talents des Cités en Provence-Alpes-Côte d'Azur": "als regionaler Gewinner des Preises Création Talents des Cités in Provence-Alpes-Côte d'Azur ausgezeichnet",
