      "Avec l'application Zoove, allez au-delà des services du quotidien et découvrez de nouvelles façons de partager, jouer et créer du lien autour des animaux.": "Mit der Zoove-App entdecken Sie über alltägliche Dienstleistungen hinaus neue Möglichkeiten, gemeinsame Momente zu erleben, zu spielen und durch Tiere Verbindungen zu schaffen.",
