      "Votre expertise peut faire évoluer": "Mit Ihrer Erfahrung können Sie",
      "Vous prenez soin des animaux au quotidien. Et nous sommes convaincus que les meilleurs outils se construisent avec ceux qui connaissent réellement leur métier.": "Sie kümmern sich täglich um Tiere. Und wir sind überzeugt, dass die besten Tools gemeinsam mit Menschen entwickelt werden, die ihren Beruf wirklich kennen.",
      "C'est pourquoi nous recherchons des toiletteurs, pet sitters, vétérinaires et autres professionnels du monde animal pour découvrir Zoove Pro, tester ses fonctionnalités et partager leurs retours.": "Deshalb suchen wir Tierfriseure, Tiersitter, Tierärzte und andere Fachleute aus der Tierbranche, die Zoove Pro kennenlernen, seine Funktionen testen und uns Feedback geben möchten.",
      "Je souhaite participer": "Ich möchte teilnehmen",
