      "Mentions légales": "Impressum",
      "Informations relatives à l'éditeur, à l'hébergement et à l'utilisation du site Zoove.": "Informationen zum Betreiber, zum Hosting und zur Nutzung der Zoove-Website.",
      "1. Éditeur du site": "1. Websitebetreiber",
      "Le site Zoove est édité par :": "Die Zoove-Website wird betrieben von:",
      "Nom de l'éditeur :": "Name des Betreibers:",
