      "Détourner les fonctionnalités de Zoove à des fins de spam, de fraude ou de publicité non autorisée.":"إساءة استخدام ميزات Zoove لإرسال رسائل مزعجة أو الاحتيال أو نشر إعلانات غير مصرح بها.",
      "Article 6 : Responsabilités":"المادة 6: المسؤوليات",
      "Zoove met à disposition une plateforme facilitant la découverte de professionnels, les échanges et la gestion de certaines prestations.":"توفر Zoove منصة تسهل العثور على المتخصصين والتواصل وإدارة بعض الخدمات.",
      "Les professionnels restent responsables des prestations qu'ils réalisent et les utilisateurs restent responsables de leurs propres comportements et des informations qu'ils communiquent.":"يظل المتخصصون مسؤولين عن الخدمات التي يقدمونها، ويظل المستخدمون مسؤولين عن سلوكهم والمعلومات التي يشاركونها.",
      "Zoove s'efforce d'assurer le bon fonctionnement de ses services, sans pouvoir garantir une disponibilité permanente ou l'absence de toute interruption technique.":"تسعى Zoove إلى ضمان حسن تشغيل خدماتها، لكنها لا تستطيع ضمان توفرها باستمرار أو خلوها من الانقطاعات التقنية.",
      "Aucune disposition des présentes conditions ne vise à exclure ou limiter une responsabilité qui ne peut légalement l'être.":"لا يهدف أي بند من هذه الشروط إلى استبعاد أو تقييد مسؤولية لا يسمح القانون باستبعادها أو تقييدها.",
      "Article 7 : Données personnelles":"المادة 7: البيانات الشخصية",
      "Les modalités de collecte, d'utilisation, de conservation et de protection des données personnelles sont décrites dans la politique de confidentialité de Zoove.":"توضح سياسة الخصوصية الخاصة بـ Zoove كيفية جمع البيانات الشخصية واستخدامها والاحتفاظ بها وحمايتها.",
      "Article 8 : Modification des CGU":"المادة 8: تعديل شروط الاستخدام",
