      "Les utilisateurs seront informés des modifications importantes par un moyen approprié avant leur entrée en vigueur lorsque cela est nécessaire.":"سيتم إبلاغ المستخدمين بالتعديلات المهمة بوسيلة مناسبة قبل دخولها حيز التنفيذ عند الضرورة.",
      "Article 9 : Contact":"المادة 9: التواصل",
